<script setup>
import axios from 'axios';
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue';
import { Link, router } from '@inertiajs/vue3';
import { route } from 'ziggy-js';
import AppLayout from '@/layouts/AppLayout.vue';
import UserNavigationTabs from '@/Components/Tabs/UserNavigationTabs.vue';
import { personalTodoCompletionNotice } from '@/utils/personalTodoRecurrence';
import { personalItemColors } from '@/utils/personalMonthCalendar';
import PersonalTodoEditor from '@/Components/Calendar/PersonalTodoEditor.vue';
const props=defineProps({workspace:Object,tab:{type:String,default:'todo'},back:Object,selected:{type:Object,default:null}});
const data=ref(props.workspace), selected=ref(props.selected), dirty=ref(false), busy=ref(false), error=ref(''), notice=ref(''),newTitle=ref(''),query=ref(props.workspace.q),sort=ref(props.workspace.sort);
const settings=reactive({...props.workspace.settings});
const listForm=reactive({id:null,name:'',color_key:'blue',version:null,request_key:globalThis.crypto.randomUUID()});
const settingsBaseline=ref(JSON.stringify(settings));
const listBaseline=ref(JSON.stringify({name:'',color_key:'blue'}));
const listDirty=computed(()=>JSON.stringify({name:listForm.name,color_key:listForm.color_key})!==listBaseline.value);
const pageDirty=computed(()=>dirty.value||(props.tab==='settings'&&JSON.stringify(settings)!==settingsBaseline.value)||(props.tab==='lists'&&listDirty.value));
let selectionSeq=0;
let quickKey=globalThis.crypto.randomUUID(),quickPayload=null,seq=0;
const views={today:'今日やる',important:'★ 重要',overdue:'期限超過',upcoming:'今後7日',undated:'期限未定',all:'すべて',inbox:'未整理',completed:'完了'};
const backArgs=computed(()=>({date:props.back?.date||undefined,calendar_view:props.back?.view||'month'}));
const backHref=computed(()=>route('calendar.index',{date:props.back?.date||undefined,view:props.back?.view||'month'}));
const headers=()=>({'X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.getAttribute('content'),Accept:'application/json'});
function discard(){return !pageDirty.value||confirm('未保存の変更を破棄して移動しますか？');}
function url(name){return route(name,backArgs.value);}
async function load(extra={}){const id=++seq;error.value='';try{const res=await axios.get(route('personal_todo.data'),{params:{view:data.value.view,q:query.value,sort:sort.value,list_id:data.value.list_id||undefined,show_completed:data.value.show_completed?1:0,page:data.value.page,...extra}});if(id===seq){data.value=res.data;syncUrl();}}catch(e){if(id===seq)error.value=e.response?.data?.message||'TODOを取得できませんでした。';}}
function syncUrl(){if(props.tab!=='todo')return;const params={...backArgs.value,view:data.value.view,q:data.value.q||undefined,sort:data.value.sort,list_id:data.value.view==='list'?data.value.list_id:undefined,page:data.value.page,show_completed:data.value.show_completed?1:0,item:selected.value?.id};const href=route('personal_todo.index',params),state=window.history.state;window.history.replaceState(state?.page?{...state,page:{...state.page,url:href}}:state,'',href);}
async function choose(item){if(busy.value||!discard())return;const seq=++selectionSeq;selected.value=null;dirty.value=false;try{const res=await axios.get(route('personal_todo.items.show',{item:item.id}));if(seq===selectionSeq){selected.value=res.data.item;syncUrl();}}catch(e){if(seq===selectionSeq)error.value=e.response?.data?.message||'詳細を取得できませんでした。';}}
async function changeView(view,list=null){if(!discard())return;selectionSeq++;selected.value=null;dirty.value=false;await load({view,list_id:list||undefined,page:1});}
async function patch(item,body,complete=false){if(busy.value||!discard())return;busy.value=true;error.value='';try{const res=complete?await axios.patch(route('personal_calendar.items.complete',{item:item.id}),{version:item.version,completed:!item.completed},{headers:headers()}):await axios.patch(route('personal_todo.items.meta',{item:item.id}),{version:item.version,...body},{headers:headers()});if(complete)notice.value=personalTodoCompletionNotice(res.data.item);if(selected.value?.id===item.id){selected.value=res.data.item;dirty.value=false;}await load();}catch(e){error.value=e.response?.data?.message||'保存できませんでした。再読み込みして確認してください。';}finally{busy.value=false;}}
async function quickAdd(){if(busy.value||!newTitle.value.trim())return;const payload={item_type:'todo',title:newTitle.value.trim(),all_day:true,color_key:'indigo',...(data.value.view==='today'?{focus_date:data.value.today}:{}),...(data.value.view==='important'?{is_important:true}:{}),...(data.value.view==='list'?{todo_list_id:data.value.list_id}:{})};if(quickPayload&&quickPayload!==JSON.stringify(payload)){error.value='前回の保存結果を確認してから、新しいTODOを追加してください。同じ内容なら再送できます。';return;}if(!discard())return;busy.value=true;error.value='';try{quickPayload=JSON.stringify(payload);const res=await axios.post(route('personal_calendar.items.store'),{...payload,request_key:quickKey},{headers:headers()});selectionSeq++;newTitle.value='';quickPayload=null;quickKey=globalThis.crypto.randomUUID();selected.value=res.data.item;dirty.value=false;notice.value='追加しました。右の詳細で期限やリストを設定できます。';await load();}catch(e){if(e.response?.status===422)quickPayload=null;error.value=Object.values(e.response?.data?.errors||{}).flat().join(' ')||e.response?.data?.message||'保存結果が不明です。同じ内容で再送するか、登録済みか確認してください。';}finally{busy.value=false;}}
async function saved(item){selectionSeq++;selected.value=item;dirty.value=false;await load();}
async function deleted(){selectionSeq++;selected.value=null;dirty.value=false;await load();}
function closeDetail(){if(discard()){selectionSeq++;selected.value=null;dirty.value=false;syncUrl();}}
function editList(list,force=false){if(!force&&listDirty.value&&!confirm('未保存のリスト編集を破棄しますか？'))return;Object.assign(listForm,{id:list?.id||null,name:list?.name||'',color_key:list?.color_key||'blue',version:list?.version||null,request_key:globalThis.crypto.randomUUID()});listBaseline.value=JSON.stringify({name:listForm.name,color_key:listForm.color_key});}
async function saveList(archive){if(busy.value)return;busy.value=true;error.value='';try{const payload={...listForm,...(archive===undefined?{}:{archived:archive})};const res=listForm.id?await axios.put(route('personal_todo.lists.update',{list:listForm.id}),payload,{headers:headers()}):await axios.post(route('personal_todo.lists.store'),payload,{headers:headers()});data.value.lists=res.data.lists;editList(null,true);notice.value='リストを保存しました。';}catch(e){error.value=Object.values(e.response?.data?.errors||{}).flat().join(' ')||e.response?.data?.message||'リストを保存できませんでした。';}finally{busy.value=false;}}
async function moveList(list,dir){if(busy.value)return;const rows=data.value.lists.filter(l=>!l.archived);const i=rows.findIndex(l=>l.id===list.id),next=i+dir;if(next<0||next>=rows.length)return;[rows[i],rows[next]]=[rows[next],rows[i]];busy.value=true;error.value='';try{const res=await axios.post(route('personal_todo.lists.reorder'),{items:rows.map(l=>({id:l.id,version:l.version}))},{headers:headers()});data.value.lists=res.data.lists;if(listForm.id)listForm.version=res.data.lists.find(l=>l.id===listForm.id)?.version||listForm.version;}catch(e){error.value=e.response?.data?.message||'並び順を保存できませんでした。';}finally{busy.value=false;}}
async function saveSettings(){if(busy.value)return;busy.value=true;error.value='';try{const res=await axios.put(route('personal_todo.settings.update'),settings,{headers:headers()});Object.assign(settings,res.data.settings);settingsBaseline.value=JSON.stringify(settings);notice.value='表示設定を保存しました。';}catch(e){error.value=e.response?.data?.message||'設定を保存できませんでした。';}finally{busy.value=false;}}
let stopNavigation;
function beforeUnload(e){if(!pageDirty.value)return;e.preventDefault();e.returnValue='';}
onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);stopNavigation=router.on('before',event=>{if(!discard())event.preventDefault();});});
onBeforeUnmount(()=>{seq++;selectionSeq++;window.removeEventListener('beforeunload',beforeUnload);stopNavigation?.();});
</script>
<template>
<AppLayout title="個人TODO">
    <template #header><div class="flex items-center gap-3"><Link :href="backHref" class="whitespace-nowrap rounded bg-gray-200 px-3 py-1.5 text-sm font-medium text-gray-700 hover:bg-gray-300">← カレンダーに戻る</Link><h2 class="text-base font-semibold text-gray-800 sm:text-xl">個人TODO（試用）</h2></div></template>
    <template #tabs><UserNavigationTabs active="calendar" /></template>
    <div class="space-y-4">
        <nav class="flex gap-2 rounded bg-white p-3 shadow"><Link v-for="(label,key) in {todo:'TODO',lists:'リスト管理',settings:'表示設定'}" :key="key" :href="url(key==='todo'?'personal_todo.index':'personal_todo.'+key)" class="rounded px-4 py-2 text-sm" :class="tab===key?'bg-blue-600 text-white':'text-blue-700 hover:bg-blue-50'">{{label}}</Link></nav>
        <p class="text-xs text-gray-500">本人だけのTODOです。期限と「今日やる」は別に管理し、作業時間には計上されません。</p>
        <p v-if="error" role="alert" class="rounded border border-red-200 bg-red-50 p-3 text-sm text-red-700">{{error}}</p><p v-if="notice" role="status" class="text-sm text-blue-800">{{notice}}</p>
        <div v-if="tab==='todo'" class="grid items-start gap-4 lg:grid-cols-[11rem_minmax(0,1fr)] xl:grid-cols-[11rem_minmax(0,1fr)_22rem]">
            <aside :class="selected?'hidden lg:block':''" class="rounded border bg-white p-3"><button v-for="(label,key) in views" :key="key" type="button" class="flex w-full justify-between rounded px-2 py-2 text-left text-sm" :class="data.view===key?'bg-blue-50 font-semibold text-blue-800':'hover:bg-gray-50'" @click="changeView(key)"><span>{{label}}</span><span class="text-xs text-gray-500">{{data.counts[key]||0}}</span></button><h3 class="mt-4 px-2 text-xs font-semibold text-gray-500">マイリスト</h3><button v-for="list in data.lists.filter(l=>!l.archived)" :key="list.id" type="button" class="mt-1 w-full break-words rounded px-2 py-2 text-left text-sm hover:bg-blue-50" :class="data.view==='list'&&data.list_id===list.id?'bg-blue-50 text-blue-800':''" @click="changeView('list',list.id)"><span class="mr-2 inline-block h-2 w-2 rounded-full" :style="{backgroundColor:personalItemColors[list.color_key]?.hex}"></span>{{list.name}}</button></aside>
            <div :class="selected?'hidden xl:block':''" class="min-w-0 space-y-4">
                <section v-if="data.view!=='completed'" aria-labelledby="todo-add-heading" class="rounded border border-blue-200 bg-blue-50 p-4">
                    <h3 id="todo-add-heading" class="mb-1 font-semibold text-blue-900">新しいTODOを追加</h3>
                    <p class="mb-3 text-xs text-blue-800">名前だけで登録できます。期限やメモは追加後に設定できます。</p>
                    <form class="flex flex-wrap gap-2" @submit.prevent="quickAdd">
                        <label for="todo-new-title" class="sr-only">新しいTODOの名前</label>
                        <input id="todo-new-title" v-model="newTitle" :disabled="busy" required maxlength="255" placeholder="例：会議の資料を準備する" class="min-w-0 flex-1 rounded border bg-white p-2 text-sm" />
                        <button :disabled="busy" class="whitespace-nowrap rounded bg-blue-600 px-3 py-2 text-sm text-white disabled:opacity-50">TODOを追加</button>
                    </form>
                </section>
                <section aria-labelledby="todo-list-heading" class="min-w-0 rounded border bg-white p-4">
                    <h3 id="todo-list-heading" class="mb-4 font-semibold">{{data.view==='list'?(data.lists.find(l=>l.id===data.list_id)?.name||'マイリスト'):views[data.view]}}の一覧（{{data.total}}）</h3>
                    <form class="mb-3" @submit.prevent="load({page:1})">
                        <label for="todo-search" class="mb-1 block text-xs font-medium text-gray-600">一覧から検索</label>
                        <div class="flex gap-2"><input id="todo-search" v-model="query" type="search" maxlength="100" placeholder="名前・メモで絞り込み" class="min-w-0 flex-1 rounded border p-2 text-sm" /><button class="whitespace-nowrap rounded border px-3 py-2 text-sm">検索</button></div>
                    </form>
                    <div class="mb-3 flex flex-wrap items-center justify-between gap-3 border-b pb-3 text-xs">
                        <label class="flex items-center gap-2 text-gray-600">並び順<select v-model="sort" class="min-w-[7rem] rounded border py-1.5 pl-3 pr-9 text-gray-800" @change="load({page:1})"><option value="due">期限順</option><option value="important">重要順</option><option value="created">追加順</option></select></label>
                        <label class="flex items-center gap-1"><input type="checkbox" :checked="data.show_completed" @change="load({show_completed:$event.target.checked?1:0,page:1})" />完了も表示</label>
                    </div>
                <p v-if="!data.items.length" class="py-6 text-sm text-gray-500">該当するTODOはありません。</p>
                <ul class="divide-y"><li v-for="item in data.items" :key="item.id" class="flex items-start gap-2 py-3"><input type="checkbox" :checked="item.completed" :disabled="busy" :aria-label="item.title+'の完了切替'" class="mt-1" @change="patch(item,{},true)" /><button type="button" class="min-w-0 flex-1 text-left" @click="choose(item)"><span class="block break-words text-sm" :class="item.completed?'text-gray-400 line-through':''">{{item.title}}</span><span class="mt-1 block text-xs" :class="item.overdue?'text-red-700':'text-gray-500'">{{item.overdue?'期限超過・':''}}{{item.start_date||'期限未定'}} {{item.start_time||''}} {{item.is_my_day?'・今日やる':''}} {{item.steps.length?'・'+item.steps_done+'/'+item.steps.length:''}} {{item.repeat_label?'・'+item.repeat_label:''}}</span></button><div class="flex gap-1"><button type="button" :disabled="busy" :aria-label="item.title+'の今日やる切替'" class="rounded px-1 text-sm" :class="item.is_my_day?'text-blue-700':'text-gray-400'" @click="patch(item,{today:!item.is_my_day})">☀</button><button type="button" :disabled="busy" :aria-label="item.title+'の重要切替'" class="rounded px-1 text-lg" :class="item.is_important?'text-amber-600':'text-gray-400'" @click="patch(item,{is_important:!item.is_important})">{{item.is_important?'★':'☆'}}</button></div></li></ul>
                <div v-if="data.last_page>1" class="mt-4 flex items-center justify-between text-sm"><button type="button" :disabled="data.page<=1" class="text-blue-700 disabled:text-gray-400" @click="load({page:data.page-1})">前へ</button><span>{{data.page}} / {{data.last_page}}</span><button type="button" :disabled="data.page>=data.last_page" class="text-blue-700 disabled:text-gray-400" @click="load({page:data.page+1})">次へ</button></div>
                </section>
            </div>
            <PersonalTodoEditor v-if="selected" :key="selected.id" :item="selected" :lists="data.lists" :today="data.today" @dirty="dirty=$event" @saved="saved" @deleted="deleted" @close="closeDetail" /><p v-else class="hidden rounded border bg-white p-5 text-sm text-gray-500 xl:block">TODOを選ぶと、ここで詳しく編集できます。</p>
        </div>
        <section v-else-if="tab==='lists'" class="grid items-start gap-4 md:grid-cols-2">
            <div class="rounded border bg-white p-4"><h3 class="mb-3 font-semibold">マイリスト</h3><p class="mb-3 text-xs text-gray-500">アーカイブしても中のTODOは残り、「すべて」や検索から確認できます。</p><div v-for="list in data.lists" :key="list.id" class="flex items-center justify-between gap-2 border-t py-3 text-sm"><button class="min-w-0 flex-1 break-words text-left text-blue-700" @click="editList(list)">{{list.name}}{{list.archived?'（アーカイブ）':''}}</button><div v-if="!list.archived" class="flex gap-2"><button :disabled="busy" :aria-label="list.name+'を上へ'" @click="moveList(list,-1)">↑</button><button :disabled="busy" :aria-label="list.name+'を下へ'" @click="moveList(list,1)">↓</button></div></div></div>
            <form class="space-y-3 rounded border bg-white p-4" @submit.prevent="saveList()"><h3 class="font-semibold">{{listForm.id?'リストを編集':'リストを追加'}}</h3><label class="block text-sm">名前<input v-model="listForm.name" required maxlength="80" class="mt-1 w-full rounded border p-2" /></label><label class="block text-sm">色<select v-model="listForm.color_key" class="mt-1 w-full rounded border p-2"><option v-for="(label,key) in {blue:'青',indigo:'藍',teal:'青緑',green:'緑',yellow:'黄',orange:'橙',red:'赤',pink:'ピンク',purple:'紫',gray:'灰',cyan:'水色'}" :key="key" :value="key">{{label}}</option></select></label><div class="flex flex-wrap justify-end gap-3"><button v-if="listForm.id" type="button" :disabled="busy" class="text-sm text-gray-600 underline" @click="editList(null)">新規へ</button><button v-if="listForm.id" type="button" :disabled="busy" class="rounded border px-3 py-2 text-sm" @click="saveList(!data.lists.find(l=>l.id===listForm.id)?.archived)">{{data.lists.find(l=>l.id===listForm.id)?.archived?'復元する':'アーカイブする'}}</button><button :disabled="busy" class="rounded bg-blue-600 px-4 py-2 text-sm text-white">保存</button></div></form>
        </section>
        <form v-else class="max-w-xl space-y-4 rounded border bg-white p-5" @submit.prevent="saveSettings"><h3 class="font-semibold">本人の表示設定</h3><label class="block text-sm">最初に開く一覧<select v-model="settings.initial_view" class="mt-1 w-full rounded border p-2"><option v-for="key in ['all','today','important','upcoming','undated']" :key="key" :value="key">{{views[key]}}</option></select></label><label class="block text-sm">並び順<select v-model="settings.default_sort" class="mt-1 w-full rounded border p-2"><option value="due">期限順</option><option value="important">重要順</option><option value="created">追加順</option></select></label><label class="block text-sm">カレンダー左の一覧<select v-model="settings.sidebar_view" class="mt-1 w-full rounded border p-2"><option value="upcoming">今日やる・期限が近い・期限超過</option><option value="today">今日やる</option><option value="all">すべての未完了</option></select></label><label class="block text-sm">左欄の最大表示件数<select v-model="settings.sidebar_limit" class="mt-1 w-full rounded border p-2"><option v-for="n in [5,10,20,30]" :key="n" :value="n">{{n}}件</option></select></label><label class="flex items-center gap-2 text-sm"><input v-model="settings.show_completed" type="checkbox" />専用ページでは完了も表示する</label><div class="flex justify-end"><button :disabled="busy" class="rounded bg-blue-600 px-4 py-2 text-sm text-white">設定を保存</button></div></form>
    </div>
</AppLayout>
</template>
